def summarize_scores(scores: list[int]) -> dict:
    if not scores:
        return {'count': 0, 'avg': 0.0, 'passed': 0}
    c = len(scores)
    avg = round(sum(scores) / c, 2)
    passed = sum(1 for s in scores if s >= 50)
    return {'count': c, 'avg': avg, 'passed': passed}

